#include <bits/stdc++.h>
using namespace std;

struct Point {
    int v, w, x, y, z;
    Point(int a, int b, int c, int d, int e) : v(a), w(b), x(c), y(d), z(e) {}
    double mag() const {
        return sqrt(v * v + w * w + x * x + y * y + z * z);
    }
};

bool angle(const Point& a, const Point& b) {
    double amag = a.mag();
    double bmag = b.mag();
    double abmag = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
    double cosine = abmag / (amag * bmag);
    // Clamp cosine to [-1,1] to avoid floating point errors
    if (cosine > 1.0) cosine = 1.0;
    if (cosine < -1.0) cosine = -1.0;
    double angleDeg = acos(cosine) * 180.0 / M_PI;
    return angleDeg < 90;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        int a, b, c, d, e;
        cin >> a >> b >> c >> d >> e;
        points.emplace_back(a, b, c, d, e);
    }
    std::unordered_set<int> good;
    for (int i = 0; i < n; i++) {
        bool isGood = true;
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                if (i != j && i != k && j != k) {
                    Point one = points[j];
