                    Point lol1(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                    if (angle(lol1, lol2)) {
                        isGood = false;
                    }
                }
            }
        }
        if (isGood) {
            good.insert(i + 1);
        }
    }
    if (good.empty()) {
        cout << 0 << "\n";
    } else {
        cout << good.size() << "\n";
        for (int idx : good) {
            cout << idx << "\n";
        }
    }
    return 0;
}

